rowCss:
#glimpse-md-dock-panel .glimpse-md-dock-row {
  display: block; white-space: pre; cursor: pointer; font-size: 12.5px;
  padding: 1px 8px 1px 0;
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  color: #cdd2d8; border-left: 3px solid transparent;
  position: relative;
}
#glimpse-md-dock-panel .glimpse-md-dock-row::before {
  content: ""; position: absolute; top: 0; bottom: 0; pointer-events: none;
  left: 10px; width: calc(var(--glimpseDockDepth, 0) * 14px);
  background-image:
    repeating-linear-gradient(to right, transparent 0, transparent 55px, rgba(205,216,232,0.20) 55px, rgba(205,216,232,0.20) 56px),
    repeating-linear-gradient(to right, transparent 0, transparent 13px, hsla(205,48%,66%,0.20) 13px, hsla(205,48%,66%,0.20) 14px, transparent 14px, transparent 84px),
    repeating-linear-gradient(to right, transparent 0, transparent 27px, hsla(150,40%,60%,0.20) 27px, hsla(150,40%,60%,0.20) 28px, transparent 28px, transparent 84px),
    repeating-linear-gradient(to right, transparent 0, transparent 41px, hsla(45,45%,62%,0.20) 41px, hsla(45,45%,62%,0.20) 42px, transparent 42px, transparent 84px),
    repeating-linear-gradient(to right, transparent 0, transparent 55px, hsla(15,50%,66%,0.20) 55px, hsla(15,50%,66%,0.20) 56px, transparent 56px, transparent 84px),
    repeating-linear-gradient(to right, transparent 0, transparent 69px, hsla(275,40%,70%,0.20) 69px, hsla(275,40%,70%,0.20) 70px, transparent 70px, transparent 84px),
    repeating-linear-gradient(to right, transparent 0, transparent 83px, hsla(185,40%,58%,0.20) 83px, hsla(185,40%,58%,0.20) 84px);
}
#glimpse-md-dock-panel .glimpse-md-dock-bullet {
  font-size: 0.8em; color: #8a9099;
}
#glimpse-md-dock-panel .glimpse-md-dock-bullet--halo {
  color: #cfe6ff;
  border-radius: 50%;
  box-shadow: 0 0 0 3px rgba(102,179,255,0.35), 0 0 4px 2px rgba(102,179,255,0.45);
}
#glimpse-md-dock-panel .glimpse-md-dock-icon {
  display: inline-block; margin-right: 5px;
}
#glimpse-md-dock-panel .glimpse-md-dock-label { }
#glimpse-md-dock-panel .glimpse-md-dock-row:hover { background: rgba(255,255,255,0.05); }
#glimpse-md-dock-panel .glimpse-md-dock-row.selected {
  background: rgba(102,179,255,0.16); color: #f5f6f8;
  border-left: 3px solid #66b3ff;
}
#glimpse-md-dock-panel .glimpse-md-dock-marker {
  display: inline-block; width: 10px; color: #66b3ff;
}
